import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.security.GeneralSecurityException;
import java.util.function.Consumer;
import javax.crypto.Cipher;
import javax.crypto.CipherOutputStream;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;

final class StreamCodec {
    static final int OPERATION = Cipher.DECRYPT_MODE;

    static void transform(byte[] input, SecretKey key, byte[] nonce, byte[] aad,
                          Consumer<byte[]> publish)
            throws GeneralSecurityException, IOException {
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(OPERATION, key, new GCMParameterSpec(128, nonce));
        cipher.updateAAD(aad);
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        try (CipherOutputStream output = new CipherOutputStream(buffer, cipher)) {
            output.write(input);
        }
        publish.accept(buffer.toByteArray());
    }
}

